body.script:
const GAME_LIST = [
  { name: "gnmath 1", url: "https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/all/refs/heads/main/gnmath1.xml" }
  { name: "gnmath 2", url: "https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/all/refs/heads/main/gnmath2.xml" },
  { name: "all slash game", url: "https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/all/refs/heads/main/slashallga.xml" },
  { name: "all deltamath game", url: "https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/all/refs/heads/main/deltamathall.xml" },
  { name: "pixel chat", url: "https://raw.githubusercontent.com/nguyenkhoinguyen08012012-stack/c9c9c9/refs/heads/main/z6/2.xml" }
];

const DB_NAME = 'GameCacheDB';
const STORE_NAME = 'GameFiles';
const CACHE_DURATION = 90 * 24 * 60 * 60 * 1000;

let CURRENT_FILE_URL = null;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      db.createObjectStore(STORE_NAME, { keyPath: 'url' });
    };
    request.onsuccess = (event) => resolve(event.target.result);
    request.onerror = (event) => reject(event.target.error);
  });
}

async function saveToCache(url, content) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readwrite');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.put({ url: url, content: content, timestamp: Date.now() });
    request.onsuccess = () => resolve();
    request.onerror = () => reject(new Error('Cache error'));
  });
}

async function getFileFromCache(url) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const transaction = db.transaction(STORE_NAME, 'readonly');
    const store = transaction.objectStore(STORE_NAME);
    const request = store.get(url);

    request.onsuccess = async (event) => {
      const data = event.target.result;
      if (data && (Date.now() - data.timestamp) < CACHE_DURATION) {
        resolve(data.content);
      } else {
        try {
          const response = await fetch(url);
          const text = await response.text();
          await saveToCache(url, text);
          resolve(text);
        } catch (err) {
          reject(err);
        }
      }
    };

    request.onerror = () => reject(new Error('DB error'));
  });
}

function buildMenu() {
  const menu = document.getElementById("menu");
  menu.innerHTML = "";

  GAME_LIST.forEach(game => {
    const btn = document.createElement("button");
    btn.className = "menu-btn";
    btn.textContent = game.name;
    btn.onclick = () => PlayTo(game.url);
    menu.appendChild(btn);
  });
}

window.onload = buildMenu;

function PlayTo(url) {
  CURRENT_FILE_URL = url;
  const iframe = document.getElementById("fr");

  getFileFromCache(url).then((text) => {
    iframe.style.display = "block";
    iframe.contentDocument.open();
    iframe.contentDocument.write(text);
    iframe.contentDocument.close();

    document.getElementById("menu").style.display = "none";
    document.getElementById("backBtn").style.display = "block";
    document.getElementById("fsBtn").style.display = "block";
  }).catch((err) => {
    console.error('Error:', err);
    alert('Game failed to load.');
  });
}

function goBack() {
  const oldIframe = document.getElementById("fr");
  oldIframe.remove();

  const newIframe = document.createElement("iframe");
  newIframe.id = "fr";
  newIframe.width = "100%";
  newIframe.height = "100%";
  newIframe.frameBorder = "0";
  newIframe.allowFullscreen = true;
  newIframe.style.display = "none";
  newIframe.style.background = "#000";

  document.getElementById("container").prepend(newIframe);

  document.getElementById("menu").style.display = "block";
  document.getElementById("backBtn").style.display = "none";
  document.getElementById("fsBtn").style.display = "none";

  CURRENT_FILE_URL = null;
}

function openFullscreen() {
  if (!CURRENT_FILE_URL) {
    alert("Select a game first.");
    return;
  }

  getFileFromCache(CURRENT_FILE_URL).then((text) => {
    const newWindow = window.open("", "_blank");
    if (newWindow) {
      newWindow.document.open();
      newWindow.document.write(text);
      newWindow.document.close();
    } else {
      alert('Fullscreen failed.');
    }
  }).catch((err) => {
    console.error('Error:', err);
    alert('Fullscreen failed to load.');
  });
}
